// ─── DATA LAYER ──────────────────────────────────────────────────────────────
var GREETINGS_DATA = {
  "ar": {
    countryName : "Argentina",
    flag        : "🇦🇷",
    greeting    : "¡Hola desde Argentina!",
    lang        : "es-AR"
  },
  "co": {
    countryName : "Colombia",
    flag        : "🇨🇴",
    greeting    : "¡Hola desde Colombia!",
    lang        : "es-CO"
  },
  "pe": {
    countryName : "Perú",
    flag        : "🇵🇪",
    greeting    : "¡Hola desde Perú!",
    lang        : "es-PE"
  },
  "mx": {
    countryName : "México",
    flag        : "🇲🇽",
    greeting    : "¡Hola desde México!",
    lang        : "es-MX"
  },
  "us": {
    countryName : "USA",
    flag        : "🇺🇸",
    greeting    : "Hello from the USA!",
    lang        : "en-US"
  },
  "es": {
    countryName : "España",
    flag        : "🇪🇸",
    greeting    : "¡Hola desde España!",
    lang        : "es-ES"
  }
};

// ─── DOM REFERENCES ───────────────────────────────────────────────────────────
var dropdownTrigger  = document.getElementById('dropdown-trigger');
var dropdownPanel    = document.getElementById('dropdown-panel');
var greetingDisplay  = document.getElementById('greeting-display');
var greetingText     = document.getElementById('greeting-text');
var greetingCountry  = document.getElementById('greeting-country');
var greetingFlag     = document.getElementById('greeting-flag');
var dropdownOptions  = document.querySelectorAll('.dropdown-option');

// ─── FUNCTIONS ────────────────────────────────────────────────────────────────
function updateGreeting(countryId) {
  var data = GREETINGS_DATA[countryId];
  if (!data) { return; }
  greetingText.textContent    = data.greeting;
  greetingCountry.textContent = data.countryName;
  greetingFlag.textContent    = data.flag;
  greetingDisplay.setAttribute('lang', data.lang);
}

function closeDropdown() {
  dropdownPanel.classList.remove('is-active');
  dropdownTrigger.classList.remove('is-active');
  dropdownTrigger.setAttribute('aria-expanded', 'false');
}

function toggleDropdown() {
  dropdownPanel.classList.toggle('is-active');
  dropdownTrigger.classList.toggle('is-active');
  var isOpen = dropdownPanel.classList.contains('is-active');
  dropdownTrigger.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
}

function handleOptionClick(event) {
  var clickedOption = event.currentTarget;
  var countryId     = clickedOption.getAttribute('data-country-id');
  updateGreeting(countryId);
  closeDropdown();
  for (var i = 0; i < dropdownOptions.length; i++) {
    dropdownOptions[i].classList.remove('is-active');
  }
  clickedOption.classList.add('is-active');
}

function handleOutsideClick(event) {
  var countrySelector = document.getElementById('country-selector');
  if (countrySelector.contains(event.target)) { return; }
  if (dropdownPanel.classList.contains('is-active')) {
    closeDropdown();
  }
}

function init() {
  dropdownTrigger.addEventListener('click', toggleDropdown);

  for (var i = 0; i < dropdownOptions.length; i++) {
    dropdownOptions[i].addEventListener('click', handleOptionClick);
  }

  document.addEventListener('click', handleOutsideClick);

  updateGreeting('ar');
}

// ─── ENTRY POINT ──────────────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', init);

/* ============================================================
   SECCIÓN 1: RESET + VARIABLES
   ============================================================ */

*, *::before, *::after {
  box-sizing: border-box;
}

:root {
  --color-primary:      #0057B8;
  --color-primary-dark: #003F8A;
  --color-surface:      #FFFFFF;
  --color-bg:           #F4F6F9;
  --color-text:         #1A1A2E;
  --color-text-muted:   #6B7280;
  --color-border:       #E2E8F0;
  --color-hover-bg:     #EFF6FF;
  --color-shadow:       rgba(0, 0, 0, 0.10);

  --font-family:        'Inter', sans-serif;
  --font-size-base:     16px;
  --font-size-sm:       0.875rem;
  --font-size-lg:       1.125rem;
  --font-size-xl:       1.5rem;
  --font-size-2xl:      2rem;
  --font-size-hero:     2.75rem;

  --radius-sm:          6px;
  --radius-md:          12px;
  --radius-lg:          20px;

  --spacing-xs:         4px;
  --spacing-sm:         8px;
  --spacing-md:         16px;
  --spacing-lg:         24px;
  --spacing-xl:         40px;
  --spacing-2xl:        64px;

  --transition-fast:    150ms ease;
  --transition-base:    250ms ease;

  --dropdown-shadow:    0 8px 24px rgba(0, 0, 0, 0.12);
  --card-shadow:        0 4px 16px rgba(0, 0, 0, 0.08);
  --max-width:          960px;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
}

/* ============================================================
   SECCIÓN 2: LAYOUT BASE
   ============================================================ */

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
  width: 100%;
}

#site-header {
  background-color: var(--color-primary);
  padding: var(--spacing-md) 0;
  box-shadow: 0 2px 8px var(--color-shadow);
}

#site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-md);
}

main {
  padding: var(--spacing-2xl) 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-xl);
}

/* ============================================================
   SECCIÓN 3: TIPOGRAFÍA
   ============================================================ */

#main-title {
  font-size: var(--font-size-hero);
  font-weight: 700;
  color: var(--color-surface);
  letter-spacing: -0.5px;
  line-height: 1.2;
}

#greeting-text {
  font-size: var(--font-size-xl);
  font-weight: 600;
  color: var(--color-text);
  text-align: center;
  margin: 0;
}

#greeting-country {
  color: var(--color-primary);
  font-weight: 700;
}

#greeting-flag {
  font-size: 2.5rem;
  line-height: 1;
  display: block;
  text-align: center;
  margin-bottom: var(--spacing-sm);
}

/* ============================================================
   SECCIÓN 4: BOTONES
   ============================================================ */

.tsoft-btn {
  background: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-sm);
  font-size: var(--font-size-base);
  font-weight: 500;
  transition:
    background-color var(--transition-fast),
    color var(--transition-fast);
}

#dropdown-trigger {
  background-color: var(--color-surface);
  color: var(--color-text);
  border: 1px solid var(--color-border);
}

#dropdown-trigger:hover {
  background-color: var(--color-hover-bg);
}

#dropdown-trigger.is-active {
  background-color: var(--color-hover-bg);
  border-color: var(--color-primary);
}

.trigger-arrow {
  display: inline-block;
  transition: transform var(--transition-base);
  font-size: var(--font-size-sm);
}

#dropdown-trigger.is-active .trigger-arrow {
  transform: rotate(180deg);
}

/* ============================================================
   SECCIÓN 5: COUNTRY SELECTOR WRAPPER
   ============================================================ */

#country-selector {
  position: relative;
  display: inline-block;
}

/* ============================================================
   SECCIÓN 6: DROPDOWN PANEL
   ============================================================ */

#dropdown-panel {
  position: absolute;
  top: calc(100% + var(--spacing-xs));
  right: 0;
  min-width: 220px;
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--dropdown-shadow);
  list-style: none;
  padding: var(--spacing-xs) 0;
  margin: 0;
  z-index: 100;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-8px);
  transition:
    opacity var(--transition-base),
    transform var(--transition-base);
}

#dropdown-panel.is-active {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

/* ============================================================
   SECCIÓN 7: OPCIONES DEL DROPDOWN
   ============================================================ */

.dropdown-option {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-md);
  cursor: pointer;
  transition: background-color var(--transition-fast);
  list-style: none;
}

.dropdown-option:hover {
  background-color: var(--color-hover-bg);
}

.dropdown-option.is-active {
  background-color: var(--color-hover-bg);
  color: var(--color-primary);
  font-weight: 600;
}

.flag-emoji {
  font-size: var(--font-size-lg);
  line-height: 1;
  flex-shrink: 0;
}

.country-name {
  font-size: var(--font-size-base);
  color: var(--color-text);
}

.dropdown-option.is-active .country-name {
  color: var(--color-primary);
  font-weight: 600;
}

/* ============================================================
   SECCIÓN 8: TARJETA DE SALUDO
   ============================================================ */

.card-greeting {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--card-shadow);
  padding: var(--spacing-xl);
  width: 100%;
  max-width: 560px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-md);
}

#greeting-display {
  opacity: 0;
  pointer-events: none;
  transform: translateY(-8px);
  transition:
    opacity var(--transition-base),
    transform var(--transition-base);
}

#greeting-display.is-active {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

/* ============================================================
   SECCIÓN 9: RESPONSIVE
   ============================================================ */

@media (max-width: 600px) {
  #main-title {
    font-size: var(--font-size-2xl);
  }

  .card-greeting {
    padding: var(--spacing-lg);
  }

  #greeting-text {
    font-size: var(--font-size-lg);
  }
}
